import {it,expect,vi} from 'vitest'
import {fixture} from './fixture'
import {LongmixRun,validateSceneIndex} from './session'
const h='a'.repeat(64),entry={id:h,sha256:h,url:'/listen/longmix-lab/v1/'+h+'.json',title:'trial',fromTitle:'A',toTitle:'B',duration:40}
it('accepts only immutable same-origin scene data addresses',()=>{expect(validateSceneIndex({schema:'harbeat.longmix-index.v1',scenes:[entry]})).toHaveLength(1);expect(()=>validateSceneIndex({schema:'harbeat.longmix-index.v1',scenes:[{...entry,url:'https://evil.test/file'}]})).toThrow()})
it('preparation failure cannot start audio and keeps normal fallback possible',async()=>{const create=vi.fn();const run=new LongmixRun(new URL('https://app.test/listen/'),()=>{},undefined,{read:async()=>{throw Error('offline')},create});await expect(run.prepare()).rejects.toThrow('offline');await expect(run.start()).rejects.toThrow();expect(create).not.toHaveBeenCalled();expect(run.snapshot().playing).toBe(false);run.stop();expect(run.snapshot().scene).toBeNull()})
it('rejects scene body digest mismatch before allocating audio',async()=>{const create=vi.fn();const run=new LongmixRun(new URL('https://app.test/listen/'),()=>{},undefined,{read:async()=>({schema:'harbeat.longmix-index.v1',scenes:[entry]}),bytes:async()=>new TextEncoder().encode('{}').buffer,create});await run.prepare();await expect(run.loadScene(h,'long')).rejects.toThrow(/指纹/);expect(create).not.toHaveBeenCalled();expect(run.snapshot().playing).toBe(false)})
it('never substitutes an unrequested variant or unknown scene',async()=>{const run=new LongmixRun(new URL('https://app.test/listen/'),()=>{},undefined,{read:async()=>({schema:'harbeat.longmix-index.v1',scenes:[entry]})});await run.prepare();await expect(run.loadScene('b'.repeat(64),'long')).rejects.toThrow();await expect(run.loadScene(h,'fake' as any)).rejects.toThrow()})
async function retryFixture(){const raw=new TextEncoder().encode(JSON.stringify(fixture())).buffer,digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(v=>v.toString(16).padStart(2,'0')).join('');vi.stubGlobal('location',{href:'https://app.test/longmix.html'});const closed=vi.fn(async()=>{}),create=vi.fn(()=>({audioWorklet:{addModule:async()=>{throw Error('worklet failed')}},close:closed} as any));const run=new LongmixRun(new URL('https://app.test/listen/'),()=>{},undefined,{create,read:async()=>({schema:'harbeat.longmix-index.v1',scenes:[{...entry,sha256:digest,url:'/listen/longmix-lab/v1/'+digest+'.json'}]}),bytes:async()=>raw});await run.prepare();return{run,create,closed}}
it('failed audio initialization releases context and retries fresh',async()=>{const{run,create,closed}=await retryFixture();await expect(run.loadScene(h,'long')).rejects.toThrow('worklet failed');await expect(run.loadScene(h,'long')).rejects.toThrow('worklet failed');expect(create).toHaveBeenCalledTimes(2);expect(closed).toHaveBeenCalledTimes(2);run.dispose()})

function suspendedStart(){let release!:()=>void;const resume=vi.fn(()=>new Promise<void>(r=>release=r)),run=new LongmixRun(new URL('https://app.test/listen/'),()=>{});Object.assign(run,{ctx:{resume,suspend:vi.fn(async()=>{})},monitor:{port:{postMessage:vi.fn()}},scene:fixture(),pcm:{},phase:'ready'});return{run,release:()=>release(),resume}}
it('serializes starts while audio focus resumes',async()=>{const{run,release,resume}=suspendedStart();const first=run.start(),reject=expect(first).rejects.toMatchObject({name:'AbortError'});await expect(run.start()).rejects.toThrow('尚未就绪');expect(resume).toHaveBeenCalledTimes(1);run.stop();release();await reject;expect(run.snapshot().playing).toBe(false)})
it('a stopped pending start cannot revive an old scene',async()=>{const{run,release}=suspendedStart();const first=run.start(),reject=expect(first).rejects.toMatchObject({name:'AbortError'});run.stop();release();await reject;expect(run.snapshot().scene).toBeNull();expect(run.snapshot().playing).toBe(false)})
